        </div>
      </div>

      {/* Full-Screen Convention & Stream QR Code Modal */}
      {showQrModal && (
        <div
          className="fixed inset-0 z-[7000] bg-black/90 backdrop-blur-xl flex items-center justify-center p-4 animate-fade-in"
