                    onClick={() => setCategory('character')}
                    className={`py-3 px-4 rounded-lg text-xs font-black uppercase tracking-widest transition-colors text-left border cursor-pointer ${
                      category === 'character'
                        ? 'bg-zinc-800 border-[#fe9a00] text-white'
