                      </th>
                      <th className="p-4 text-[10px] font-black uppercase tracking-widest text-zinc-500">
                        Name / Title
                      </th>
                      <th className="p-4 text-[10px] font-black uppercase tracking-widest text-[#fe9a00] text-right">
                        Final Score
                      </th>
