                  </thead>
                  <tbody>
                    {(Array.isArray(rankingData) ? rankingData : []).map(
                      (row: any, index: number) => (
                        <tr
                          key={index}
                          className="border-b border-zinc-800/50 hover:bg-zinc-900 transition-colors"
                        >
                          <td className="p-4 text-center">
                            <span
                              className={`text-sm font-black ${
                                index === 0
                                  ? 'text-yellow-400'
                                  : index === 1
                                  ? 'text-zinc-300'
                                  : index === 2
                                  ? 'text-amber-600'
                                  : 'text-zinc-600'
                              }`}
                            >
                              #{index + 1}
                            </span>
                          </td>
                          <td className="p-4">
                            <div className="flex items-center gap-3">
                              {(row.avatar_url || row.cover_url) && (
                                <img
                                  src={row.avatar_url || row.cover_url}
                                  className="w-8 h-8 rounded-full object-cover border border-zinc-700 bg-black"
                                  alt="avatar"
                                />
                              )}
                              <div>
                                <p className="text-sm font-bold text-white leading-none">
                                  {row.name || row.title || row.username || 'Unknown'}
                                </p>
                                {row.series_slug && (
                                  <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mt-1">
                                    {row.series_slug}
                                  </p>
                                )}
                              </div>
                            </div>
                          </td>
                          <td className="p-4 text-right">
                            <span className="text-sm font-black text-white">
                              {(row.score || 0).toLocaleString()}
                            </span>
                          </td>
                        </tr>
                      )
                    )}
                    {(!Array.isArray(rankingData) || rankingData.length === 0) && (
                      <tr>
                        <td
                          colSpan={3}
                          className="p-12 text-center text-zinc-600 font-bold uppercase tracking-widest text-xs"
                        >
                          No data recorded for this period.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

interface DailyChartBucket {
  dateKey: string;
  label: string;
  shortLabel: string;
  reads: number;
  signups: number;
  engagements: number;
}

export const AnalyticsDashboard = () => {
  const { seriesList = [] } = useSeriesData();
  const [activeTab, setActiveTab] = useState<'global' | 'engagement' | 'series' | 'leaderboards'>(
    'global'
  );
  const [isLoading, setIsLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [lastRefreshed, setLastRefreshed] = useState<Date>(new Date());

  const [globalStats, setGlobalStats] = useState<any>(null);
  const [growthStats, setGrowthStats] = useState<any>(null);
  const [engagementBreakdown, setEngagementBreakdown] = useState<any>(null);
  const [dailyTimeline, setDailyTimeline] = useState<DailyChartBucket[]>([]);
  const [recentUsers, setRecentUsers] = useState<any[]>([]);
  const [recentActivityFeed, setRecentActivityFeed] = useState<any[]>([]);
  const [seriesStats, setSeriesStats] = useState<any[]>([]);
  const [telemetryStats, setTelemetryStats] = useState<any>(null);

  // Series Table Filtering & Sorting
  const [seriesSearch, setSeriesSearch] = useState('');
  const [seriesSortKey, setSeriesSortKey] = useState<
    'score' | 'reads' | 'hypes' | 'ctr' | 'comments' | 'trend'
  >('score');

  const fetchAnalytics = useCallback(async () => {
    setIsLoading(true);
    setDbError(null);
    try {
      const [
        globalRpcRes,
        seriesRpcRes,
        telemetryRpcRes,
        profilesRes,
        seriesTableRes,
        chaptersTableRes,
        readingHistoryRes,
        completedReadsRes,
        hypesRes,
        superHypesRes,
        pageReactsRes,
        seriesCommentsRes,
        seriesLikesRes,
        creatorTipsRes
      ] = await Promise.all([
        supabase.rpc('get_advanced_app_health'),
        supabase.rpc('get_series_health_analytics'),
        supabase.rpc('get_telemetry_stats'),
        supabase.from('profiles').select('*'),
        supabase.from('series').select('*'),
        supabase.from('chapters').select('id, series_slug, chapter_number, title'),
        supabase.from('reading_history').select('*'),
        supabase.from('completed_reads').select('*'),
        supabase.from('hypes').select('*'),
        supabase.from('super_hypes').select('*'),
        supabase.from('page_reacts').select('*'),
        supabase.from('series_comments').select('*'),
        supabase.from('series_likes').select('*'),
        supabase.from('creator_tips').select('*')
      ]);

      const now = new Date();
      const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      const startOfYesterday = new Date(startOfToday);
      startOfYesterday.setDate(startOfToday.getDate() - 1);

      const startOfWeek = new Date(startOfToday);
      startOfWeek.setDate(startOfToday.getDate() - 7);
      const startOfLastWeek = new Date(startOfWeek);
      startOfLastWeek.setDate(startOfWeek.getDate() - 7);

      const startOfMonth = new Date(startOfToday);
      startOfMonth.setDate(startOfToday.getDate() - 30);
      const startOfLastMonth = new Date(startOfMonth);
      startOfLastMonth.setDate(startOfMonth.getDate() - 30);

      const startOfQuarter = new Date(startOfToday);
      startOfQuarter.setDate(startOfToday.getDate() - 90);
      const startOfLastQuarter = new Date(startOfQuarter);
      startOfLastQuarter.setDate(startOfQuarter.getDate() - 90);

      const startOfYear = new Date(startOfToday);
      startOfYear.setDate(startOfToday.getDate() - 365);
      const startOfLastYear = new Date(startOfYear);
      startOfLastYear.setDate(startOfYear.getDate() - 365);

      // --- 1. USER GROWTH & PROFILES ---
      const profiles = profilesRes.data || [];
      const totalUsersLive = profiles.length;
      const premiumUsersLive = profiles.filter((p: any) => p.is_premium).length;
      const freeUsersLive = Math.max(0, totalUsersLive - premiumUsersLive);

      const profileDates = profiles
        .map((p: any) => {
          const raw = p.created_at || p.updated_at;
          return raw ? new Date(raw) : null;
        })
        .filter((d): d is Date => Boolean(d && !isNaN(d.getTime())));

      const countDatesBetween = (dates: Date[], start: Date, end?: Date) =>
        dates.filter(d => d >= start && (!end || d < end)).length;

      const newUsersToday = countDatesBetween(profileDates, startOfToday);
      const newUsersYesterday = countDatesBetween(profileDates, startOfYesterday, startOfToday);
      const newUsersWeek = countDatesBetween(profileDates, startOfWeek);
      const newUsersLastWeek = countDatesBetween(profileDates, startOfLastWeek, startOfWeek);
      const newUsersMonth = countDatesBetween(profileDates, startOfMonth);
      const newUsersLastMonth = countDatesBetween(profileDates, startOfLastMonth, startOfMonth);

      setGrowthStats({
        newUsersToday,
        newUsersYesterday,
        newUsersWeek,
        newUsersLastWeek,
        newUsersMonth,
        newUsersLastMonth
      });

      // Top 8 most recent user signups
      const sortedRecentUsers = [...profiles]
        .sort((a: any, b: any) => {
          const da = new Date(a.created_at || a.updated_at || 0).getTime();
          const db = new Date(b.created_at || b.updated_at || 0).getTime();
          return db - da;
        })
        .slice(0, 8);
      setRecentUsers(sortedRecentUsers);

      // --- 2. GLOBAL READS & ACTIVE USERS ---
      const historyRows = readingHistoryRes.data || [];
      const completedRows = completedReadsRes.data || [];
      const readEvents =
        historyRows.length >= completedRows.length
          ? historyRows.map((r: any) => new Date(r.updated_at || r.created_at || now))
          : completedRows.map((r: any) => new Date(r.created_at || now));

      const active7dSet = new Set<string>();
      const active30dSet = new Set<string>();
      historyRows.forEach((r: any) => {
        const rawDt = r.updated_at || r.created_at;
        if (r.user_id && rawDt) {
          const dt = new Date(rawDt);
          if (dt >= startOfWeek) active7dSet.add(r.user_id);
          if (dt >= startOfMonth) active30dSet.add(r.user_id);
        }
      });

      const sumProfileReads = profiles.reduce(
        (acc: number, p: any) => acc + (Number(p.chapters_read) || 0),
        0
      );
      const liveReadsLifetime = Math.max(
        readEvents.length,
        completedRows.length,
        sumProfileReads
      );

      const rpcGlobal = globalRpcRes.data || {};
      const finalTotalUsers = Math.max(Number(rpcGlobal.total_users || 0), totalUsersLive);
      const finalActive30d = Math.max(Number(rpcGlobal.active_30d || 0), active30dSet.size);

      setGlobalStats({
        total_users: finalTotalUsers,
        premium_users: premiumUsersLive,
        free_users: Math.max(finalTotalUsers - premiumUsersLive, freeUsersLive),
        active_7d: active7dSet.size,
        active_30d: finalActive30d,
        reads_today: Math.max(
          Number(rpcGlobal.reads_today || 0),
          countDatesBetween(readEvents, startOfToday)
        ),
        reads_yesterday: Math.max(
          Number(rpcGlobal.reads_yesterday || 0),
          countDatesBetween(readEvents, startOfYesterday, startOfToday)
        ),
        reads_week: Math.max(
          Number(rpcGlobal.reads_week || 0),
          countDatesBetween(readEvents, startOfWeek)
        ),
        reads_last_week: Math.max(
          Number(rpcGlobal.reads_last_week || 0),
          countDatesBetween(readEvents, startOfLastWeek, startOfWeek)
        ),
        reads_month: Math.max(
          Number(rpcGlobal.reads_month || 0),
          countDatesBetween(readEvents, startOfMonth)
        ),
        reads_last_month: Math.max(
          Number(rpcGlobal.reads_last_month || 0),
          countDatesBetween(readEvents, startOfLastMonth, startOfMonth)
        ),
        reads_quarter: Math.max(
          Number(rpcGlobal.reads_quarter || 0),
          countDatesBetween(readEvents, startOfQuarter)
        ),
        reads_last_quarter: Math.max(
          Number(rpcGlobal.reads_last_quarter || 0),
          countDatesBetween(readEvents, startOfLastQuarter, startOfQuarter)
        ),
        reads_year: Math.max(
          Number(rpcGlobal.reads_year || 0),
          countDatesBetween(readEvents, startOfYear)
        ),
        reads_last_year: Math.max(
          Number(rpcGlobal.reads_last_year || 0),
          countDatesBetween(readEvents, startOfLastYear, startOfYear)
        ),
        reads_lifetime: Math.max(Number(rpcGlobal.reads_lifetime || 0), liveReadsLifetime)
      });

      // --- 3. 14-DAY DAILY TIMELINE BUCKETS ---
      const buckets: DailyChartBucket[] = [];
      const bucketMap = new Map<string, DailyChartBucket>();
      for (let i = 13; i >= 0; i--) {
        const d = new Date(startOfToday);
        d.setDate(startOfToday.getDate() - i);
        const key = d.toISOString().split('T')[0];
        const label = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        const shortLabel = d.toLocaleDateString('en-US', { weekday: 'short' });
        const bucket: DailyChartBucket = {
          dateKey: key,
          label,
          shortLabel,
          reads: 0,
          signups: 0,
          engagements: 0
        };
        buckets.push(bucket);
        bucketMap.set(key, bucket);
      }

      readEvents.forEach(dt => {
        if (!isNaN(dt.getTime())) {
          const key = dt.toISOString().split('T')[0];
          const b = bucketMap.get(key);
          if (b) b.reads += 1;
        }
      });

      profileDates.forEach(dt => {
        if (!isNaN(dt.getTime())) {
          const key = dt.toISOString().split('T')[0];
          const b = bucketMap.get(key);
          if (b) b.signups += 1;
        }
      });

      const hypesData = hypesRes.data || [];
      const superHypesData = superHypesRes.data || [];
      const reactsData = pageReactsRes.data || [];
      const commentsData = seriesCommentsRes.data || [];
      const likesData = seriesLikesRes.data || [];
      const tipsData = creatorTipsRes.data || [];

      [...hypesData, ...superHypesData, ...reactsData, ...commentsData, ...likesData].forEach(
        (ev: any) => {
          const raw = ev.created_at || ev.updated_at;
          if (raw) {
            const dt = new Date(raw);
            if (!isNaN(dt.getTime())) {
              const key = dt.toISOString().split('T')[0];
              const b = bucketMap.get(key);
              if (b) b.engagements += 1;
            }
          }
        }
      );

      setDailyTimeline(buckets);

      // --- 4. WHAT USERS ARE ENGAGING WITH (BREAKDOWN & PULSE) ---
      const totalTipDollars = tipsData.reduce(
        (sum: number, t: any) => sum + (Number(t.amount_dollars) || 0),
        0
      );

      setEngagementBreakdown({
        chapterReads: liveReadsLifetime,
        completedChapters: completedRows.length,
        standardHypes: hypesData.length,
        superHypes: superHypesData.length,
        quickReacts: reactsData.length,
        seriesLikes: likesData.length,
        comments: commentsData.length,
        creatorTipsCount: tipsData.length,
        creatorTipsDollars: totalTipDollars
      });

      // Build Series & Chapter lookup maps for the Live Activity Pulse
      const chaptersList = chaptersTableRes.data || [];
      const chapToSeries = new Map<string, string>();
      const chapToNumber = new Map<string, number>();
      chaptersList.forEach((c: any) => {
        chapToSeries.set(String(c.id), c.series_slug);
        if (c.chapter_number !== undefined) {
          chapToNumber.set(String(c.id), Number(c.chapter_number));
        }
      });

      const seriesTitleMap = new Map<string, string>();
      (seriesTableRes.data || seriesList || []).forEach((s: any) => {
        if (s.slug) seriesTitleMap.set(s.slug, s.title || s.slug);
      });

      const feedItems: any[] = [];
      superHypesData.slice(-8).forEach((sh: any) => {
        feedItems.push({
          type: 'super_hype',
          label: `Super Hype dropped on ${
            seriesTitleMap.get(sh.series_slug) || sh.series_slug || 'a series'
          }`,
          timestamp: sh.created_at || now.toISOString()
        });
      });
      commentsData.slice(-8).forEach((cm: any) => {
        feedItems.push({
          type: 'comment',
          label: `${cm.user_name || 'A fan'} commented on ${
            seriesTitleMap.get(cm.series_slug) || cm.series_slug || 'a series'
          }`,
          sub: cm.text ? `"${String(cm.text).slice(0, 65)}"` : '',
          timestamp: cm.created_at || now.toISOString()
        });
      });
      tipsData.slice(-8).forEach((tp: any) => {
        feedItems.push({
          type: 'tip',
          label: `${tp.donor_name || 'A supporter'} tipped $${tp.amount_dollars || 5} to ${
            tp.creator_name || 'Creator'
          }`,
          sub: tp.fan_message ? `"${String(tp.fan_message).slice(0, 65)}"` : '',
          timestamp: tp.created_at || now.toISOString()
        });
      });
      historyRows.slice(-10).forEach((rh: any) => {
        const sSlug = chapToSeries.get(String(rh.chapter_id));
        const chNum = chapToNumber.get(String(rh.chapter_id));
        if (sSlug) {
          feedItems.push({
            type: 'read',
            label: `Reader opened ${seriesTitleMap.get(sSlug) || sSlug}${
              chNum ? ` • Ch. ${chNum}` : ''
            }`,
            timestamp: rh.updated_at || rh.created_at || now.toISOString()
          });
        }
      });

      feedItems.sort(
        (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
      );
      setRecentActivityFeed(feedItems.slice(0, 12));

      // --- 5. COMPUTE VERIFIED SERIES HEALTH ---
      const readsPerSeries: Record<string, number> = {};
      const currentMonthReadsPerSeries: Record<string, number> = {};
      const lastMonthReadsPerSeries: Record<string, number> = {};

      historyRows.forEach((r: any) => {
        const slug = chapToSeries.get(String(r.chapter_id));
        if (slug) {
          readsPerSeries[slug] = (readsPerSeries[slug] || 0) + 1;
          const dt = new Date(r.updated_at || r.created_at || now);
          if (dt >= startOfMonth) {
            currentMonthReadsPerSeries[slug] = (currentMonthReadsPerSeries[slug] || 0) + 1;
          } else if (dt >= startOfLastMonth && dt < startOfMonth) {
            lastMonthReadsPerSeries[slug] = (lastMonthReadsPerSeries[slug] || 0) + 1;
          }
        }
      });

      completedRows.forEach((r: any) => {
        const slug = chapToSeries.get(String(r.chapter_id));
        if (slug && !readsPerSeries[slug]) {
          readsPerSeries[slug] = (readsPerSeries[slug] || 0) + 1;
        }
      });

      const hypesPerSeries: Record<string, number> = {};
      superHypesData.forEach((sh: any) => {
        if (sh.series_slug) {
          hypesPerSeries[sh.series_slug] = (hypesPerSeries[sh.series_slug] || 0) + 1;
        }
      });
      hypesData.forEach((h: any) => {
        if (h.target_type === 'series' && h.target_id) {
          hypesPerSeries[h.target_id] = (hypesPerSeries[h.target_id] || 0) + 1;
        } else if (h.target_type === 'chapter' && h.target_id) {
          const slug = chapToSeries.get(String(h.target_id));
          if (slug) hypesPerSeries[slug] = (hypesPerSeries[slug] || 0) + 1;
        }
      });
      likesData.forEach((sl: any) => {
        if (sl.series_slug) {
          hypesPerSeries[sl.series_slug] = (hypesPerSeries[sl.series_slug] || 0) + 1;
        }
      });

      const reactsPerSeries: Record<string, number> = {};
      reactsData.forEach((pr: any) => {
        const slug = chapToSeries.get(String(pr.chapter_id));
        if (slug) reactsPerSeries[slug] = (reactsPerSeries[slug] || 0) + 1;
      });

      const commentsPerSeries: Record<string, number> = {};
      commentsData.forEach((sc: any) => {
        if (sc.series_slug) {
          commentsPerSeries[sc.series_slug] = (commentsPerSeries[sc.series_slug] || 0) + 1;
        }
      });

      const rpcSeriesArray = Array.isArray(seriesRpcRes.data) ? seriesRpcRes.data : [];
      const rpcSeriesMap = new Map<string, any>();
      rpcSeriesArray.forEach((s: any) => {
        if (s.series_slug || s.slug) rpcSeriesMap.set(s.series_slug || s.slug, s);
      });

      const rawSeriesSource =
        seriesTableRes.data && seriesTableRes.data.length > 0
          ? seriesTableRes.data
          : seriesList && seriesList.length > 0
          ? seriesList
          : rpcSeriesArray;

      const visibleSeries = rawSeriesSource.filter((s: any) => s.is_hidden !== true);

      const mergedSeriesStats = visibleSeries.map((s: any) => {
        const slug = s.slug || s.series_slug;
        const rpcItem = rpcSeriesMap.get(slug) || {};

        const totalReads = Math.max(Number(rpcItem.total_reads || 0), readsPerSeries[slug] || 0);
        const pageVisits = Math.max(Number(rpcItem.page_visits || 0), totalReads);
        const totalHypes = Math.max(
          Number(rpcItem.total_hypes || 0),
          hypesPerSeries[slug] || 0,
          Number(s.total_hype || s.hype_count || 0)
        );
        const totalReacts = Math.max(Number(rpcItem.total_reacts || 0), reactsPerSeries[slug] || 0);
        const totalComments = Math.max(
          Number(rpcItem.total_comments || 0),
          commentsPerSeries[slug] || 0
        );
        const ctr =
          pageVisits > 0
            ? Math.min(100, (totalReads / pageVisits) * 100)
            : Number(rpcItem.ctr_percentage || 0);

        const curM = currentMonthReadsPerSeries[slug] || 0;
        const lastM = lastMonthReadsPerSeries[slug] || 0;
        const liveTrend = lastM > 0 ? ((curM - lastM) / lastM) * 100 : curM > 0 ? 100 : 0;
        const trendPct =
          rpcItem.trend_percentage !== undefined && Number(rpcItem.trend_percentage) !== 0
            ? Number(rpcItem.trend_percentage)
            : liveTrend;

        const engagementScore =
          totalReads + totalHypes * 5 + totalReacts * 2 + totalComments * 3;

        return {
          series_slug: slug,
          title: s.title || rpcItem.title || 'Unknown Series',
          creator_name: s.creator_name || 'Saturday AM',
          cover_url: s.cover_url || rpcItem.cover_url,
          trend_percentage: trendPct,
          page_visits: pageVisits,
          total_reads: totalReads,
          ctr_percentage: ctr,
          total_hypes: totalHypes,
          total_reacts: totalReacts,
          total_comments: totalComments,
          engagement_score: engagementScore
        };
      });

      setSeriesStats(mergedSeriesStats);

      if (telemetryRpcRes.data) {
        setTelemetryStats(telemetryRpcRes.data);
      }
      setLastRefreshed(new Date());
    } catch (error: any) {
      console.error('Analytics Error:', error);
      setDbError(error.message || 'Unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  }, [seriesList]);

  useEffect(() => {
    fetchAnalytics();

    const subscription = supabase
      .channel('realtime_analytics')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'reading_history' }, () => {
        fetchAnalytics();
      })
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'completed_reads' },
        () => {
          fetchAnalytics();
        }
      )
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'hypes' }, () => {
        fetchAnalytics();
      })
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'super_hypes' }, () => {
        fetchAnalytics();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(subscription);
    };
  }, [fetchAnalytics]);

  const sortedAndFilteredSeries = useMemo(() => {
    const q = seriesSearch.trim().toLowerCase();
    const filtered = (seriesStats || []).filter(
      s =>
        !q ||
        String(s.title || '')
          .toLowerCase()
          .includes(q) ||
        String(s.creator_name || '')
          .toLowerCase()
          .includes(q)
    );

    return [...filtered].sort((a, b) => {
      if (seriesSortKey === 'reads') return b.total_reads - a.total_reads;
      if (seriesSortKey === 'hypes') return b.total_hypes - a.total_hypes;
      if (seriesSortKey === 'ctr') return b.ctr_percentage - a.ctr_percentage;
      if (seriesSortKey === 'comments') return b.total_comments - a.total_comments;
      if (seriesSortKey === 'trend') return b.trend_percentage - a.trend_percentage;
      return b.engagement_score - a.engagement_score;
    });
  }, [seriesStats, seriesSearch, seriesSortKey]);

  const maxEngagementScore = useMemo(() => {
    if (!seriesStats || seriesStats.length === 0) return 1;
    return Math.max(1, ...seriesStats.map(s => s.engagement_score || 0));
  }, [seriesStats]);

  const maxDailyReads = useMemo(() => {
    if (!dailyTimeline || dailyTimeline.length === 0) return 1;
    return Math.max(1, ...dailyTimeline.map(d => Math.max(d.reads, d.signups)));
  }, [dailyTimeline]);

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-24 gap-4">
        <RefreshCw className="w-8 h-8 text-[#fe9a00] animate-spin" />
        <span className="text-zinc-400 font-black uppercase tracking-widest text-[11px]">
          Crunching Real-Time Growth & Engagement Data...
        </span>
      </div>
    );
  }

  const conversionRate =
    globalStats?.total_users > 0
      ? ((globalStats?.premium_users / globalStats?.total_users) * 100).toFixed(1)
      : '0.0';

  const activeRetentionRate =
    globalStats?.total_users > 0
      ? Math.min(100, (globalStats?.active_30d / globalStats?.total_users) * 100).toFixed(1)
      : '0.0';

  const avgReadsPerUser =
    globalStats?.total_users > 0
      ? (globalStats?.reads_lifetime / globalStats?.total_users).toFixed(1)
      : '0.0';

  return (
    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 shadow-2xl max-w-6xl mx-auto relative text-white space-y-6">
      {/* ERROR DISPLAY BOX */}
      {dbError && (
        <div className="bg-red-500/10 border border-red-500/50 p-4 rounded-xl flex items-start gap-3">
          <AlertTriangle className="w-5 h-5 text-red-500 flex-shrink-0" />
          <div>
            <h3 className="text-red-500 font-black uppercase tracking-widest text-[10px] mb-1">
              Database Sync Warning
            </h3>
            <p className="text-zinc-300 text-xs font-bold leading-relaxed">{dbError}</p>
          </div>
        </div>
      )}

      {/* TOP HEADER BAR */}
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4 border-b border-zinc-800 pb-5">
        <div>
          <div className="flex items-center gap-2 text-[#fe9a00] text-[10px] font-black uppercase tracking-widest mb-1">
            <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
            Saturday AM • Command Center Intelligence
          </div>
          <div className="flex items-center gap-3">
            <Activity className="w-6 h-6 text-[#fe9a00]" />
            <h2 className="text-2xl font-black uppercase italic tracking-wider text-white">
              App Growth & Engagement Engine
            </h2>
          </div>
        </div>

        <div className="flex items-center gap-3 self-start sm:self-auto">
          <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">
            Synced {lastRefreshed.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </span>
          <button
            onClick={fetchAnalytics}
            className="flex items-center gap-2 px-3.5 py-2 rounded-xl bg-black border border-zinc-800 hover:border-[#fe9a00] text-zinc-300 hover:text-white text-[10px] font-black uppercase tracking-widest transition-all cursor-pointer"
          >
            <RefreshCw className="w-3.5 h-3.5 text-[#fe9a00]" /> Refresh Live Data
          </button>
        </div>
      </div>

      {/* NAVIGATION TABS */}
      <div className="flex flex-wrap bg-black p-1.5 rounded-xl border border-zinc-800 gap-1.5">
        <button
          onClick={() => setActiveTab('global')}
          className={`flex-1 min-w-[130px] py-2.5 px-4 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all cursor-pointer flex items-center justify-center gap-2 ${
            activeTab === 'global'
              ? 'bg-[#fe9a00] text-black shadow-[0_0_20px_rgba(254,154,0,0.3)]'
              : 'text-zinc-400 hover:text-white'
          }`}
        >
          <TrendingUp className="w-3.5 h-3.5" /> Growth & Overview
        </button>

        <button
          onClick={() => setActiveTab('engagement')}
          className={`flex-1 min-w-[140px] py-2.5 px-4 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all cursor-pointer flex items-center justify-center gap-2 ${
            activeTab === 'engagement'
              ? 'bg-[#fe9a00] text-black shadow-[0_0_20px_rgba(254,154,0,0.3)]'
              : 'text-zinc-400 hover:text-white'
          }`}
        >
          <Flame className="w-3.5 h-3.5" /> Feature Engagement
        </button>

        <button
          onClick={() => setActiveTab('series')}
          className={`flex-1 min-w-[130px] py-2.5 px-4 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all cursor-pointer flex items-center justify-center gap-2 ${
            activeTab === 'series'
              ? 'bg-[#fe9a00] text-black shadow-[0_0_20px_rgba(254,154,0,0.3)]'
              : 'text-zinc-400 hover:text-white'
          }`}
        >
          <Layers className="w-3.5 h-3.5" /> Series Performance
        </button>

        <button
          onClick={() => setActiveTab('leaderboards')}
          className={`flex-1 min-w-[140px] py-2.5 px-4 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all cursor-pointer flex items-center justify-center gap-2 ${
            activeTab === 'leaderboards'
              ? 'bg-[#fe9a00] text-black shadow-[0_0_20px_rgba(254,154,0,0.3)]'
              : 'text-zinc-400 hover:text-white'
          }`}
        >
          <Award className="w-3.5 h-3.5" /> Leaderboard Archive
        </button>
      </div>

      {/* ===================================================================== */}
      {/* TAB 1: GROWTH & OVERVIEW                                              */}
      {/* ===================================================================== */}
      {activeTab === 'global' && globalStats && (
        <div className="space-y-6 animate-fade-in">
          {/* EXECUTIVE KPI CARDS */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Total Users */}
            <div className="bg-gradient-to-br from-black via-zinc-950 to-blue-950/20 border border-zinc-800 p-5 rounded-2xl flex flex-col justify-between">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2.5">
                  <div className="p-2 bg-blue-500/15 border border-blue-500/30 rounded-xl">
                    <Users className="w-4 h-4 text-blue-400" />
                  </div>
                  <span className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">
                    Total Accounts
                  </span>
                </div>
                {growthStats && (
                  <TrendBadge
                    current={growthStats.newUsersMonth}
                    past={growthStats.newUsersLastMonth}
                    label="30d"
                  />
                )}
              </div>
              <div className="flex items-baseline justify-between">
                <span className="text-3xl font-black tracking-tight text-white">
                  {(globalStats.total_users || 0).toLocaleString()}
                </span>
                <span className="text-[10px] font-bold text-blue-400">
                  +{growthStats?.newUsersWeek || 0} this wk
                </span>
              </div>
            </div>

            {/* Subscribers & Conversion */}
            <div className="bg-gradient-to-br from-black via-zinc-950 to-purple-950/25 border border-purple-500/30 p-5 rounded-2xl flex flex-col justify-between">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2.5">
                  <div className="p-2 bg-purple-500/15 border border-purple-500/30 rounded-xl">
                    <Crown className="w-4 h-4 text-purple-400" />
                  </div>
                  <span className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">
                    PLUS Subscribers
                  </span>
                </div>
                <span className="text-purple-300 font-black text-[10px] bg-purple-500/20 border border-purple-500/30 px-2 py-0.5 rounded-full">
                  {conversionRate}% Conv.
                </span>
              </div>
              <div className="flex items-baseline justify-between">
                <span className="text-3xl font-black tracking-tight text-white">
                  {(globalStats.premium_users || 0).toLocaleString()}
                </span>
                <span className="text-[10px] font-bold text-zinc-500">
                  {(globalStats.free_users || 0).toLocaleString()} Free
                </span>
              </div>
            </div>

            {/* 30-Day Active & Stickiness */}
            <div className="bg-gradient-to-br from-black via-zinc-950 to-amber-950/25 border border-[#fe9a00]/40 p-5 rounded-2xl flex flex-col justify-between">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2.5">
                  <div className="p-2 bg-[#fe9a00]/15 border border-[#fe9a00]/30 rounded-xl">
                    <Activity className="w-4 h-4 text-[#fe9a00]" />
                  </div>
                  <span className="text-[10px] text-[#fe9a00] font-black uppercase tracking-widest">
