                  day.reads > 0 ? 8 : 2,
                  Math.round((day.reads / maxDailyReads) * 100)
                );
                const signupHeightPct = Math.max(
                  day.signups > 0 ? 8 : 2,
                  Math.round((day.signups / maxDailyReads) * 100)
                );

                return (
                  <div
                    key={day.dateKey}
                    className="flex-1 flex flex-col items-center h-full justify-end group relative"
