  { code: 'NL', name: 'Netherlands' }, { code: 'BE', name: 'Belgium' }, { code: 'CH', name: 'Switzerland' }, { code: 'AT', name: 'Austria' },
  { code: 'NO', name: 'Norway' }, { code: 'FI', name: 'Finland' }, { code: 'DK', name: 'Denmark' },
